#!/usr/bin/env python3
"""Compile every US decompilation source and find its code in the target (EU) executable.

The US decompilation describes another build of the same game. Its sources still describe the same
source code, so compiling one with the original compiler and searching the target's functions for
the result tells us, function by function, whether that source carries over as it stands.

Function boundaries come from the target's splat output (build/splat/asm/nonmatchings/core/text/
*.s, one file per function, generated by tools/splat.sh from your own copy of the game): they
include functions nothing calls, which a `jal` scan misses.

An entry is:
  exact     the compiled words are byte-identical to a target function
  masked    identical once call/jump targets and address-like `lui` halves are ignored
            (only addresses differ: the source carries over, its symbols need remapping)
  none      no masked-equal target function of the same length

usage: src_map.py TARGET.elf --splat ASM_DIR --src DIR --out map.txt [--jobs N] [--limit N]
"""
import argparse
import collections
import concurrent.futures
import glob
import os
import re
import struct
import subprocess
import tempfile

COMPILER = os.path.expanduser('~/.local/share/gt4/ee-gcc2.96')
NONMATCHING = re.compile(r'\s*nonmatching\s+(\w+),\s*(0x[0-9A-Fa-f]+)')


def load_words(path):
    d = open(path, 'rb').read()
    e_shoff, = struct.unpack_from('<I', d, 32)
    shentsize, shnum = struct.unpack_from('<HH', d, 46)
    S = [struct.unpack_from('<IIIIIIIIII', d, e_shoff + i * shentsize) for i in range(shnum)]
    secs = [dict(type=s[1], addr=s[3], off=s[4], size=s[5]) for s in S]
    code = max((s for s in secs if s['type'] == 1 and s['size'] > 1 << 20), key=lambda s: s['size'])
    words = list(struct.unpack_from('<%dI' % (code['size'] // 4), d[code['off']:code['off'] + code['size']]))
    return code['addr'], words


def splat_functions(asm_dir):
    """address -> length in words, from splat's one-file-per-function output."""
    out = {}
    for p in glob.glob(os.path.join(asm_dir, '**', '*.s'), recursive=True):
        with open(p, errors='replace') as f:
            head = [next(f, '') for _ in range(4)]
        for line in head:
            m = NONMATCHING.match(line)
            if m:
                out[int(m.group(1).split('_')[-1], 16)] = max(1, int(m.group(2), 16) // 4)
                break
    return out


def mask(w):
    op = w >> 26
    if op in (2, 3):
        return w & 0xFC000000
    if op == 15:
        return w & 0xFFFF0000 if 0x00100000 <= ((w & 0xFFFF) << 16) <= 0x00900000 else w
    return w


def object_text(path):
    d = open(path, 'rb').read()
    e_shoff, = struct.unpack_from('<I', d, 32)
    shentsize, shnum, shstr = struct.unpack_from('<HHH', d, 46)
    S = [struct.unpack_from('<IIIIIIIIII', d, e_shoff + i * shentsize) for i in range(shnum)]
    so = S[shstr][4]
    nm = lambda o: d[so + o:d.index(b'\0', so + o)].decode('latin1')
    text = None
    for s in S:
        if nm(s[0]) == '.text' and s[5]:
            text = d[s[4]:s[4] + s[5]]
    if not text:
        return None
    return list(struct.unpack_from('<%dI' % (len(text) // 4), text))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('target')
    ap.add_argument('--splat', required=True)
    ap.add_argument('--src', required=True)
    ap.add_argument('--out', required=True)
    ap.add_argument('--jobs', type=int, default=max(1, (os.cpu_count() or 4)))
    ap.add_argument('--limit', type=int, default=0)
    ap.add_argument('--compiler', default=COMPILER)
    ap.add_argument('--include', action='append', default=[])
    a = ap.parse_args()

    base, words = load_words(a.target)
    funcs = splat_functions(a.splat)
    print(f'target: {len(funcs):,} splat functions, {len(words):,} words', flush=True)
    index = collections.defaultdict(list)
    for addr, n in funcs.items():
        i = (addr - base) // 4
        if i + n > len(words):
            continue
        index[(n, tuple(mask(words[i + j]) for j in range(min(n, 4))))].append(addr)

    srcs = sorted(p for p in glob.glob(os.path.join(a.src, '**', '*'), recursive=True)
                  if p.endswith(('.cpp', '.c', '.cc')))
    if a.limit:
        srcs = srcs[:a.limit]
    print(f'sources: {len(srcs):,}', flush=True)
    includes = a.include or [os.path.join(a.src, '..', 'include')]
    tmp = tempfile.mkdtemp(prefix='srcmap-')

    def one(items):
        i, src = items
        obj = os.path.join(tmp, f'{i}.o')
        r = subprocess.run([f'{a.compiler}/bin/ee-gcc', '-c', '-B', f'{a.compiler}/bin/ee-', '-O2',
                            '-G0', '-fno-exceptions', '-fno-strict-aliasing',
                            *[f'-I{x}' for x in includes], src, '-o', obj],
                           capture_output=True, text=True)
        if r.returncode != 0 or not os.path.exists(obj):
            return (src, None, 0, 'compile error')
        try:
            w = object_text(obj)
        except Exception:
            return (src, None, 0, 'compile error')
        finally:
            try:
                os.remove(obj)
            except OSError:
                pass
        if not w:
            return (src, None, 0, 'empty')
        n = len(w)
        best, at = 'not found', None
        for addr in index.get((n, tuple(mask(x) for x in w[:4])), ()):
            i2 = (addr - base) // 4
            if [mask(x) for x in w] == [mask(words[i2 + j]) for j in range(n)]:
                best = 'exact' if list(w) == list(words[i2:i2 + n]) else 'masked'
                at = addr
                if best == 'exact':
                    break
        return (src, at, n, best)

    stats = collections.Counter()
    rows = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=a.jobs) as ex:
        for src, at, n, st in ex.map(one, enumerate(srcs)):
            stats[st] += 1
            if at is not None:
                rows.append((src, at, n, st))
            done = sum(stats.values())
            if done % 2000 == 0:
                print(f'  {done:>6,}/{len(srcs):,}', flush=True)

    with open(a.out, 'w') as f:
        f.write('# source\ttarget_addr\twords\tstatus\n')
        for src, at, n, st in sorted(rows):
            f.write(f'{src}\t{at:#010x}\t{n}\t{st}\n')
    for k in ('exact', 'masked', 'not found', 'compile error', 'empty'):
        if stats[k]:
            print(f'  {k:<14} {stats[k]:>7,}')
    found = stats['exact'] + stats['masked']
    print(f'\ncarried over as they stand: {found:,}/{len(srcs):,} = '
          f'{100*found/max(1,len(srcs)):.1f}%  (exact {100*stats["exact"]/max(1,len(srcs)):.1f}%)')


if __name__ == '__main__':
    main()
